        getPerformanceSummary(history) {
            if (!history.length) return {};
            var lastRecord = history[history.length - 1];
            var results = lastRecord.results || {};
            var composite = results.composite || 0;
            var productivity = results.productivity || 0;
            var bench = results.benchStrength || 0;
            var clientSat = results.clientSatisfaction || 0;
            var engagement = results.engagement || 0;

            var performance = 'Developing Leader';
            if (composite >= 70 && bench >= 60) performance = 'Strategic Talent Leader';
            else if (composite >= 60) performance = 'Competent Manager';
            else if (composite >= 50) performance = 'Developing Leader';
            else performance = 'Needs Strategic Rethinking';

            var insights = [];
            if (bench >= 65) insights.push('Strong investment in talent development will pay long-term dividends.');
            if (bench < 40) insights.push('Bench strength is critically low. Future leadership pipeline is at risk.');
            if (productivity >= 70 && bench < 45) insights.push('High productivity masked talent erosion. A common trap in AI deployment.');
            if (composite >= 65) insights.push('Balanced approach to AI and human development. Well positioned for the future.');
            if (engagement < 40) insights.push('Low engagement signals talent retention risk. Address development culture.');
            if (clientSat >= 65) insights.push('Client satisfaction is strong. Analytical quality has been preserved.');
            if (insights.length === 0) insights.push('Review your decisions to identify where a more balanced approach could improve outcomes.');

            return {
                composite: composite,
                productivity: productivity,
                benchStrength: bench,
                clientSatisfaction: clientSat,
                engagement: engagement,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            if (results.deltaBench < -10) return window.mySimulation.t('hint_bench_drop');
            if (results.deltaProductivity > 15 && results.deltaBench < -5) return window.mySimulation.t('hint_productivity_trap');
            if (results.deltaEngagement < -8) return window.mySimulation.t('hint_engagement_drop');
            if (results.composite >= 65) return window.mySimulation.t('hint_balanced');
            if (state.domainState.benchStrength < 35) return window.mySimulation.t('hint_bench_critical');
            return null;
        }

