        _updateBriefing(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];

            var briefEl = document.getElementById('briefingText');
            if (briefEl) briefEl.innerHTML = '<strong>' + round.title + '</strong><br><br>' + round.briefing;

            var eventPanel = document.getElementById('eventPanel');
            if (eventPanel) eventPanel.style.display = 'none';

            for (var di = 0; di < 4; di++) {
                var labelEl = document.getElementById('d' + (di + 1) + 'Label');
                if (labelEl) labelEl.textContent = round.decisions[di].label;

                var selectEl = document.getElementById('d' + (di + 1) + 'Input');
                if (selectEl) {
                    var opts = round.decisions[di].options;
                    var optEls = selectEl.querySelectorAll('option');
                    var letters = ['A', 'B', 'C', 'D'];
                    for (var oi = 0; oi < letters.length; oi++) {
                        var optEl = document.getElementById('d' + (di + 1) + 'Opt' + letters[oi]);
                        if (optEl) optEl.textContent = letters[oi] + ': ' + opts[letters[oi]];
                    }
                    selectEl.value = '';
                }
            }
        }
